const FOMO_BASE = "https://api.fomoapi.io/v2/leaderboard/";

function json(data, status=200){
  return new Response(JSON.stringify(data), {
    status,
    headers: {
      "content-type":"application/json; charset=UTF-8",
      "cache-control":"public, max-age=15","x-content-type-options":"nosniff"
    }
  });
}

export default {
  async fetch(request, env){
    const url=new URL(request.url);

    if(url.pathname === "/api/search"){
      const q=url.searchParams.get("q")?.trim();
      if(!q) return json({error:"Missing search query"},400);
      try{
        const upstream=await fetch("https://api.dexscreener.com/latest/dex/search?q="+encodeURIComponent(q),{headers:{accept:"application/json"}});
        const body=await upstream.text();
        return new Response(body,{status:upstream.status,headers:{"content-type":upstream.headers.get("content-type")||"application/json","cache-control":"public, max-age=15"}});
      }catch(e){ return json({error:e?.message||"Search request failed"},502); }
    }

    if(url.pathname === "/api/token-pairs"){
      const chain=url.searchParams.get("chain")?.trim();
      const address=url.searchParams.get("address")?.trim();
      if(!chain||!address) return json({error:"Missing chain or token address"},400);
      try{
        const upstream=await fetch("https://api.dexscreener.com/token-pairs/v1/"+encodeURIComponent(chain)+"/"+encodeURIComponent(address),{headers:{accept:"application/json"}});
        const body=await upstream.text();
        return new Response(body,{status:upstream.status,headers:{"content-type":upstream.headers.get("content-type")||"application/json","cache-control":"public, max-age=15"}});
      }catch(e){ return json({error:e?.message||"Token pools request failed"},502); }
    }

    if(url.pathname === "/api/trader-profile"){
      const handle=url.searchParams.get("handle")?.trim();
      if(!handle) return json({error:"Missing trader handle"},400);
      if(!env?.FOMO_API_KEY) return json({error:"FOMO API key is not configured"},500);
      try{
        const upstream=await fetch("https://api.fomoscan.sh/v2/user/handle/"+encodeURIComponent(handle)+"/pnl",{
          headers:{accept:"application/json",authorization:`Bearer ${env.FOMO_API_KEY}`},
          cf:{cacheTtl:60,cacheEverything:false}
        });
        const body=await upstream.text();
        return new Response(body,{status:upstream.status,headers:{"content-type":upstream.headers.get("content-type")||"application/json","cache-control":"public, max-age=60"}});
      }catch(e){return json({error:e?.message||"Trader profile request failed"},502)}
    }

    if(url.pathname === "/api/thesis"){
      const token=url.searchParams.get("token")?.trim();
      if(!token) return json({error:"Missing token address"},400);
      if(!env?.FOMO_API_KEY) return json({error:"FOMO API key is not configured"},500);
      try{
        const upstream=await fetch("https://api.fomoscan.sh/v2/thesis/token/"+encodeURIComponent(token),{
          headers:{accept:"application/json",authorization:`Bearer ${env.FOMO_API_KEY}`},
          cf:{cacheTtl:60,cacheEverything:false}
        });
        const body=await upstream.text();
        return new Response(body,{status:upstream.status,headers:{"content-type":upstream.headers.get("content-type")||"application/json","cache-control":"public, max-age=60"}});
      }catch(e){return json({error:e?.message||"Trader thesis request failed"},502)}
    }

    if(url.pathname === "/api/health") return json({ok:true,service:"memescanner",time:new Date().toISOString()});

    if(url.pathname === "/api/mscan"){
      const CA="GdLGKhk5zrLRqTsWcVRWavYr5yL1L5Sop6EggoRPpump";
      try{
        const upstream=await fetch("https://api.dexscreener.com/token-pairs/v1/solana/"+CA,{headers:{accept:"application/json"}});
        if(!upstream.ok) return json({error:"DexScreener HTTP "+upstream.status},502);
        const data=await upstream.json();
        const pairs=Array.isArray(data)?data.filter(p=>p?.baseToken?.address?.toLowerCase()===CA.toLowerCase()):[];
        pairs.sort((a,b)=>(Number(b.liquidity?.usd)||0)-(Number(a.liquidity?.usd)||0));
        return json({address:CA,pair:pairs[0]||null,source:"dexscreener",updatedAt:new Date().toISOString()});
      }catch(e){return json({error:e?.message||"MSCAN market data request failed"},502)}
    }

    if(url.pathname === "/api/traders"){
      const allowed=new Set(["24h","7d","30d","all"]);
      const windowName=url.searchParams.get("window") || "24h";
      if(!allowed.has(windowName)) return json({error:"Invalid leaderboard window"},400);

      try{
        if(!env?.FOMO_API_KEY){
          return json({error:"FOMO API key is not configured"},500);
        }

        const fresh=url.searchParams.get("fresh")==="1";
        const upstream=await fetch(FOMO_BASE + windowName + "?limit=50", {
          headers:{
            accept:"application/json",
            authorization:`Bearer ${env.FOMO_API_KEY}`,
            "cache-control":fresh?"no-cache":"max-age=10"
          },
          cf:{cacheTtl:fresh?0:10, cacheEverything:false}
        });

        if(!upstream.ok){
          // Keep upstream credentials and response details out of the browser.
          if(upstream.status === 401) return json({error:"FOMO API authentication failed. Check the FOMO_API_KEY secret."},502);
          if(upstream.status === 402) return json({error:"FOMO API credits are exhausted."},502);
          if(upstream.status === 429) return json({error:"FOMO API rate limit reached. Try again shortly."},502);
          return json({error:"FOMO API HTTP "+upstream.status},502);
        }
        const data=await upstream.json();
        return json({
          source:"fomoapi",
          window:data.window || windowName,
          updatedAt:data.updatedAt || data.capturedAt || data.syncedAt || null,
          pnlBasis:data.pnlBasis || null,
          count:data.count || (data.traders?.length || 0),
          traders:Array.isArray(data.traders) ? data.traders : (Array.isArray(data.data?.traders)?data.data.traders:[])
        });
      }catch(e){
        return json({error:e?.message || "FOMO API request failed"},502);
      }
    }

    // Serve the static site.
    if(url.pathname === "/" || url.pathname === "/index.html"){
      return new Response(HTML, {
        headers:{"content-type":"text/html; charset=UTF-8","cache-control":"no-store"}
      });
    }
    return new Response("Not found",{status:404});
  }
};

